<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api} from '@/api/client'
import RunnerSettingsNav from '@/components/RunnerSettingsNav.vue'
interface Token{id:string;name:string;prefix:string;scopes:string[];paper_ids:number[]|null;expires_at:number;revoked:boolean;last_seen:number|null}
const base='/api/me/access-tokens',tokens=ref<Token[]>([]),name=ref(''),days=ref(7),paperIds=ref(''),scopes=ref(['papers:read','annotations:read']),secret=ref(''),error=ref(''),busy=ref(false)
const options=['papers:read','papers:write','annotations:read','annotations:write','files:read']
async function load(){tokens.value=(await api<{tokens:Token[]}>(base)).tokens}
onMounted(async()=>{try{await load()}catch(e){error.value=String(e)}})
async function issue(){busy.value=true;error.value='';secret.value='';try{const ids=paperIds.value.trim()?paperIds.value.split(',').map(x=>Number(x.trim())):null;if(ids?.some(x=>!Number.isSafeInteger(x)||x<1))throw Error('论文 ID 请输入逗号分隔的正整数');const result=await api<{token:string}>(base,{method:'POST',body:{name:name.value,scopes:scopes.value,expires_days:days.value,paper_ids:ids}});secret.value=result.token;await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function revoke(t:Token){busy.value=true;try{await api(base+'/'+t.id,{method:'DELETE'});await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><main class="access-page"><RunnerSettingsNav/><h1>外部智能体接入</h1><p>为当前账号签发独立授权，通过 Skill 使用论文接口。授权仅能访问选择的范围，不能调用模型、管理账号或读取连接密钥。</p><p><a href="/downloads/firework-paper-ops.zip">下载通用论文操作 Skill</a> · API 前缀：<code>/api/external/v1</code></p><p v-if="error" role="alert">{{ error }}</p><section v-if="secret" role="status"><h2>请保存授权密钥</h2><p>完整密钥仅显示一次。保存到本地权限受限的密钥文件，供客户端读取；不要粘贴到智能体对话或共享文档中。</p><textarea readonly :value="secret" aria-label="一次性授权密钥" rows="3"/><button @click="secret=''">已保存，隐藏密钥</button></section><form @submit.prevent="issue"><h2>新建授权</h2><label>用途名称<input v-model="name" required maxlength="80"/></label><label>有效天数（1–90）<input v-model.number="days" type="number" min="1" max="90" required/></label><label>限定论文 ID（逗号分隔；留空为当前账号所有论文）<input v-model="paperIds" placeholder="例如 12, 18"/></label><fieldset><legend>允许的操作</legend><label v-for="o in options" :key="o" class="check"><input v-model="scopes" type="checkbox" :value="o"/>{{ o }}</label></fieldset><p>默认只读。限定论文的授权不能创建新论文。每个授权每分钟最多 60 次请求。</p><button :disabled="busy||!scopes.length||!name.trim()">创建授权</button></form><h2>已签发授权</h2><article v-for="t in tokens" :key="t.id"><strong>{{ t.name }}</strong><p>{{ t.prefix }}… · {{ t.scopes.join(' / ') }}</p><p>论文范围：{{ t.paper_ids?.join(', ')||'当前账号所有论文' }} · 到期：{{ new Date(t.expires_at*1000).toLocaleString() }}</p><span v-if="t.revoked">已撤销</span><button v-else :disabled="busy" @click="revoke(t)">撤销授权</button></article><p v-if="!tokens.length">尚未签发授权。</p></main></template>
<style scoped>.access-page{max-width:900px;margin:auto;padding:32px 24px;line-height:1.7}form,section,article{border:1px solid var(--border,#ddd);border-radius:12px;padding:22px;margin:20px 0}label{display:grid;gap:6px;margin:14px 0}.check{display:flex;align-items:center;gap:8px}input,textarea{padding:9px;max-width:100%}textarea{width:100%;box-sizing:border-box}button{padding:8px 14px}code,article{overflow-wrap:anywhere}</style>
